import type { DocumentActivitySourceBinding, DocumentActivityStatementReference } from './document-activity.interface';
import type { TdmsRecordSummary, TdmsReadReceipt, TdmsRawCode, TdmsSourceVersion } from './tdms-source.interface';
import type { TdmsProcessingSetScope } from './tdms-processing-set.interface';
/** Saved candidate reading content. Its reading depths are never generated by GET. */
export interface AssessmentReadingContent {
  schemaVersion: 'wiselink.3_1.assessment_reading.v1';
  headline: string;
  listBrief: string;
  lead: string;
  claims: AssessmentReadingClaim[];
  /** Direct saved problem bodies; these are not fabricated atomic claims. */
  issueArticles?: Array<{ issueKey: string; issueRef: string; question: string; body: string }>;
  /** Claims whose conditions, negations or conflicts must remain visible. */
  decisiveClaimIds: string[];
}

export interface AssessmentReadingClaim {
  claimId: string;
  text: string;
  /** Model classification: SOURCE_FACT reports a source statement, not Host verification. */
  basis: 'SOURCE_FACT' | 'CONDITIONAL_INFERENCE';
  premises: AssessmentClaimPremise[];
}

export interface AssessmentClaimPremise {
  evidenceRef: string;
  role: 'SUPPORTS' | 'LIMITS' | 'CONTEXT' | 'CONFLICTS';
  explanation: string;
  limitation: string | null;
}

export interface DialogueEvidenceSource {
  requestRef: string;
  contributionRef: string;
  revision: number;
  contextWorkItemIds: string[];
}

/** Exact saved analysis identity; this is not a document or an adoption decision. */
export interface AssessmentSourceWork {
  subjectKind: 'ENGINEERING_MATTER';
  subjectId: string;
  workRef: string;
  issueKey: string;
}

/** Immutable selected cohort/member identity, not a claim of current source authority. */
export interface AssessmentTdmsProcessingSetBinding {
  scope: TdmsProcessingSetScope;
  setRevisionRef: string;
  generation: number;
  processingFamilyRef: string;
  cohortRef: string;
  processingObservationRef: string;
  memberRef: string;
  assessmentObservationRef: string;
}

export interface AssessmentTdmsApprovalObservation {
  sourceRecordId: string;
  recordKind: 'ENGINEER_ASSESSMENT';
  sourceVersion: TdmsSourceVersion;
  state: TdmsRawCode;
  sourceModifiedAt: string | null;
  observedAt: string;
  identitySelector: string;
  stateSelector: string;
  versionSelector: string;
  objectBinding: 'EXACT_CURRENT_DETAIL';
}
export interface AssessmentTdmsApprovalProvenance {
  captureRef: string;
  evidencePath: 'rawFields.opinionCollection';
  mode: 'EXACT_VERSION';
  before: AssessmentTdmsApprovalObservation;
  after: AssessmentTdmsApprovalObservation;
  approvalSubject: { sourceRecordId: string; sourceVersion: TdmsSourceVersion };
}

/** A bounded, exact native field scope. Grouping describes reading only, not a source relation. */
export interface AssessmentTdmsNativeScope {
  /** Required by new native runtime consumers; absent historical DTOs are not upgraded. */
  processingSetBinding?: AssessmentTdmsProcessingSetBinding;
  approval?: AssessmentTdmsApprovalProvenance;
  /** Exact sourced participant/discipline provenance; absent remains unknown. */
  opinionContribution?: {
    opinionRef: string;
    contributorRefs: string[];
    responsibilityRefs: string[];
    ataScopes: string[];
    assertionRefs: string[];
  };
  sourceRevisionRef: string;
  fieldSelectors: Array<{fieldPath:string;selector:string}>;
  grouping: 'SOURCE_DECLARED_BLOCK' | 'TRANSPARENT_FIELDS';
  limitations: string[];
}

/** Host-issued premises keep their original carrier identity and version. */
export type AssessmentEvidence = {
  evidenceRef: string;
  title: string;
  versionLabel: string | null;
  excerpt: string;
  dialogueSource?: DialogueEvidenceSource;
} & (
  | {
      /** External historical/source-declared record; never a current review or Host fact. */
      kind: 'TDMS_NATIVE_RECORD';
      nativeSource: TdmsRecordSummary;
      nativeScope?: AssessmentTdmsNativeScope;
      nativeReadReceipt: TdmsReadReceipt & { purpose: 'JOB_AID_NATIVE_RECORD'; taskContextRef: string; fieldPaths: string[] };
    }
  | {
      kind: 'DOCUMENT_PASSAGE';
      /** Direct document material has no WorkItem execution identity. */
      workItemId: string | null;
      documentVersionId: string;
      sourceRefId: string;
      locator: string;
    }
  | {
      kind: 'ENGINEER_STATEMENT';
      origin: 'REVIEW_CONVERSATION';
      reviewConversationId: string;
      reviewTurnId: string;
      engineerSuppliedInputId: string;
      recordedAt: string;
    }
  | {
      kind: 'ENGINEER_STATEMENT';
      origin: 'ENGINEER_REVIEW_LEDGER';
      workItemId: string;
      reviewRevision: number;
      sequence: number;
      sourceRefId: string;
      locator: string;
      recordedAt: string;
    }
  | {
      kind: 'HOST_FACT';
      workItemId: string;
      workItemRevision: number;
      factRef: string;
      recordedAt: string;
    }
  | {
      kind: 'QUERY_RECEIPT';
      receiptRef: string;
      checkedScope: string;
      queriedAt: string;
      coverage: 'COMPLETE' | 'PARTIAL';
      /** A retrieval response is supplemental material, not verified source text. */
      queryProvenance?: {
        origin: 'AILY_RETRIEVAL';
        queryText: string;
        status: 'COMPLETED' | 'FAILED' | 'UNKNOWN';
        originalDocumentsVerified: false;
      };
    }
  | {
      kind: 'PRIOR_RESULT';
      resultRef: string;
      resultRevision: number;
      /** A previous candidate is context, not a new independent source fact. */
      originalEvidenceRefs: string[];
      sourceWork?: AssessmentSourceWork;
      /** Exact saved source explanation. Mutually exclusive with sourceWork. */
      sourceStatement?: {
        reference: DocumentActivityStatementReference;
        sourceBinding: DocumentActivitySourceBinding;
      };
    }
  | {
      kind: 'ENGINEER_ATTACHMENT';
      workItemId: string;
      reviewConversationId: string;
      reviewTurnId: string;
      attachmentRef: string;
      documentVersionId: string;
      artifactRef: string;
      artifactSha256: string;
      locator: string;
    }
  | {
      kind: 'METHOD_CLAUSE';
      packRef: string;
      methodRef: string;
      sourceIdentity: string;
      locator: string;
      sourceVersionStatus: 'CONFIRMED' | 'VERSION_UNCONFIRMED';
    }
);

export interface AssessmentReadingResult {
  resultRef: string;
  resultRevision: number;
  scope:
    | { kind: 'WORK_ITEM'; workItemId: string; documentVersionId: string }
    | { kind: 'ENGINEERING_MATTER'; matterId: string };
  content: AssessmentReadingContent;
  evidence: AssessmentEvidence[];
  candidateOnly: true;
}

export interface AssessmentClaimEvidenceReadModel {
  resultRef: string;
  resultRevision: number;
  claim: AssessmentReadingClaim;
  evidence: AssessmentEvidence[];
}

/** A saved result projected for a directory row, without shortening its claims. */
export interface AssessmentReadingSummary {
  roundCompletion?: 'IN_PROGRESS' | 'COMPLETE' | 'COMPLETE_WITH_OPEN_QUESTIONS';
  resultRef: string;
  resultRevision: number;
  headline: string;
  listBrief: string;
  decisiveClaims: Array<{ claimId: string; text: string }>;
}
